interest_group_leader_weight = {
		value = {
			add = 50
			desc = "base_value"
		}
		# More likely if people are angry, or content under a Council Republic
		if = {
			limit = {
				owner ?= {
					has_law_or_variant = law_type:law_council_republic
				}
			}
			add = {
				value = owner.loyalist_fraction
				multiply = 100
				desc = "COUNTRY_LOYALISTS"
			}
		}
		else = {
			add = {
				value = owner.radical_fraction
				multiply = 100
				desc = "COUNTRY_RADICALS"
			}
		}

		# More likely if issues are relevant
		if = {
			limit = {
				owner.ideology_communist_leader_disfavoured_laws > 0
			}
			add = {
				value = owner.ideology_communist_leader_disfavoured_laws
				multiply = 8
				desc = "DISFAVORED_LAWS"
			}
		}

		# Less likely if issues are not relevant
		if = {
			limit = {
				owner.ideology_communist_leader_favoured_laws > 0
			}
			subtract = {
				value = owner.ideology_communist_leader_favoured_laws
				multiply = 8
				desc = "FAVORED_LAWS"
			}
		}

		# More likely for angry IG's outside of council republic
		if = {
			limit = {
				owner ?= {
					NOT = { has_law_or_variant = law_type:law_council_republic }
				}
				NOT = { is_interest_group_type = ig_armed_forces }
				ig_approval <= define:NPolitics|APPROVAL_THRESHOLD_UNHAPPY
			}
			subtract = {
				value = ig_approval
				multiply = 5
				desc = "IG_APPROVAL_BELOW_UNHAPPY"
			}
		}
		# More likely when SoL is low outside of council republic
		if = {
			limit = {
				owner ?= {
					NOT = { has_law_or_variant = law_type:law_council_republic }
					average_sol < average_expected_sol
				}
			}
			add = {
				value = 50
				desc = "SOL_BELOW_EXPECTED"
			}
		}
		# Labour Association Laws
		if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_factory_councils
				}
			}
			add = {
				value = 75
				desc = "FACTORY_COUNCILS_LAW"
			}
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_combination_acts
				}
			}
			add = {
				value = 50
				desc = "COMBINATION_ACTS_LAW"
			}
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					OR = {
						has_law_or_variant = law_type:law_guild_system
						has_law_or_variant = law_type:law_anti_strike_laws
					}
				}
			}
			add = {
				value = 25
				desc = "GUILDS_OR_ANTI_STRIKE_LAW"
			}
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_right_to_associate
				}
			}
			add = {
				value = -25
				desc = "RIGHT_TO_ASSOCIATE_LAW"
			}
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_corporatized_unions
				}
			}
			add = {
				value = -50
				desc = "CORPORATIZED_UNIONS_LAW"
			}
		}
		if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					active_law:lawgroup_labour_associations ?= {
						has_amendment = amendment_type:amendment_factory_councils
					}
				}
			}
			add = {
				value = 75
				desc = "FACTORY_COUNCILS_AMENDMENT"
			}
		}
		# Communal Administration favours the Trade Unions
		if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_communal_administration
				}
			}
			add = {
				value = 50
				desc = "COMMUNAL_ADMINISTRATION_LAW"
			}
		}
		# Revolutionary Guard favours the Armed Forces
		if = {
			limit = {
				is_interest_group_type = ig_armed_forces
				owner ?= {
					has_law_or_variant = law_type:law_revolutionary_guard
				}
			}
			add = {
				value = 50
				desc = "REVOLUTIONARY_GUARD_LAW"
			}
		}

		if = {
			limit = {
				owner ?= { has_variable = election_communist_support }
			}
			add = {
				value = 50
				desc = "INTERNATIONAL_SUPPORT"
			}
		}
		if = {
			limit = {
				owner ?= { has_variable = communism_1_done }
			}
			add = {
				value = 100
				desc = "COMMUNISM_1_COMPLETE"
			}
		}

		# Multiplied by inverse percent of peasants
		if = {
			limit = {
				owner ?= {
					"owner.pop_type_percent_country(pop_type:peasants)" < 0.25
				}
			}
			multiply = {
				value = 1
				add = {
					value = 1
					subtract = "owner.pop_type_percent_country(pop_type:peasants)"
				}
				desc = "LOW_PEASANTS_PERCENT"
			}
		}
		else = {
			multiply = {
				value = 0.5
				desc = "PEASANTS_PERCENT"
			}
		}

		# Multiplied by inverse GDP per capita percentage
		if = {
			limit = {
				owner.gdp_per_capita_ranking < 20 # TODO PRCAL-46014: change this out for the ratio of global average gdp per capita to gdp per capita
			}
			multiply = {
				value = 1
				add = {
					value = 100
					subtract = owner.gdp_per_capita_ranking # TODO PRCAL-46014: change this out for the ratio of global average gdp per capita to gdp per capita
					divide = 100
				}
				desc = "HIGH_GDP_PER_CAPITA"
			}
		}
		else = {
			multiply = {
				value = 0.5
				desc = "LOW_GDP_PER_CAPITA"
			}
		}

		if = { #Armed Forces should not become communist too often outside CRs.
			limit = {
				owner ?= {
					NOT = {
						has_law_or_variant = law_type:law_council_republic
					}
				}
				is_interest_group_type = ig_armed_forces
			}
			multiply = {
				value = 0.3
				desc = "ig_armed_forces"
			}
		}
		# National Liberation Alliance
		if = {
			limit = {
				owner ?= {
					has_variable = national_liberation_alliance_variable
					has_journal_entry = je_new_republic
				}
			}
			multiply = {
				value = 1.25
				desc = "NATIONAL_LIBERATION_ALLIANCE"
			}
		}
		if = {
			limit = {
				OR = {
					has_variable = chose_vanguardism
					has_variable = chose_anarchism
				}
			}
			multiply = {
				value = 0.5
				desc = "CHOSE_A_DIFFERENT_RADICAL_PATH"
			}
		}
		if = {
			limit = {
				OR = {
					has_variable = chose_conservatism
					has_variable = chose_fascism
					has_variable = chose_ethno_nationalism
				}
			}
			multiply = {
				value = 0.1
				desc = "CHOSE_A_DIFFERENT_PATH"
			}
		}
		multiply = {
			value = 1
			add = modifier:interest_group_ideology_communist_leader_leader_chance_mult
			desc = "EVENTS_AND_OTHER_EFFECTS"
		}
	}

